-- Read-only pg_catalog extraction used for hosted public ERD on 2026-10-27.
-- Project: zhzluhqvysvsadwuugpa. Both statements are SELECT only.
-- The companion unique-index-expression-check.sql tags expression indexes;
-- hosted-public-catalog.json records this as has_expression for each index.

select jsonb_build_object('captured_at_utc',now(),'project_ref','zhzluhqvysvsadwuugpa','tables',(select jsonb_agg(jsonb_build_object('name',c.relname,'kind',c.relkind,'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'position',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'nullable',not a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',nullif(a.attidentity,''),'generated',nullif(a.attgenerated,'')) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped)) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p'))) as catalog;

select jsonb_build_object('captured_at_utc',now(),'constraints',(select jsonb_agg(jsonb_build_object('name',con.conname,'table',rel.relname,'type',con.contype,'columns',(select jsonb_agg(att.attname order by k.ord) from unnest(con.conkey) with ordinality k(num,ord) join pg_attribute att on att.attrelid=con.conrelid and att.attnum=k.num),'referenced_schema',refn.nspname,'referenced_table',ref.relname,'referenced_columns',(select jsonb_agg(att.attname order by k.ord) from unnest(con.confkey) with ordinality k(num,ord) join pg_attribute att on att.attrelid=con.confrelid and att.attnum=k.num),'on_update',con.confupdtype,'on_delete',con.confdeltype,'match',con.confmatchtype,'deferrable',con.condeferrable,'validated',con.convalidated) order by rel.relname,con.conname) from pg_constraint con join pg_class rel on rel.oid=con.conrelid join pg_namespace n on n.oid=rel.relnamespace left join pg_class ref on ref.oid=con.confrelid left join pg_namespace refn on refn.oid=ref.relnamespace where n.nspname='public' and rel.relkind in ('r','p') and con.contype in ('p','u','f')),'unique_indexes',(select jsonb_agg(jsonb_build_object('name',idx.relname,'table',rel.relname,'columns',(select jsonb_agg(att.attname order by k.ord) from unnest(i.indkey::int2[]) with ordinality k(num,ord) join pg_attribute att on att.attrelid=i.indrelid and att.attnum=k.num where k.ord<=i.indnkeyatts),'predicate',pg_get_expr(i.indpred,i.indrelid),'valid',i.indisvalid,'nulls_not_distinct',i.indnullsnotdistinct) order by rel.relname,idx.relname) from pg_index i join pg_class rel on rel.oid=i.indrelid join pg_namespace n on n.oid=rel.relnamespace join pg_class idx on idx.oid=i.indexrelid where n.nspname='public' and rel.relkind in ('r','p') and i.indisunique)) as catalog;
